"""Kaggle (2x T4): prova "pagina intera" (src/museumbot/generation/vllm_wiki.py), 3 opere x
(5 testi puri + 10 misti a alpha 0.5). Clona restructure-src al commit 65c8c7e e ci scrive
sopra i file della prova, incorporati qui sotto (FILES, zlib + base64) perche' non sono
ancora sul branch remoto. Report: docs/report-pagina-intera.md.
Output: /kaggle/working/wiki.jsonl."""

import base64
import os
import subprocess
import sys
import zlib
from pathlib import Path

REPO = "/tmp/museumbot"
OUT = "/kaggle/working/wiki.jsonl"
os.environ.setdefault("HF_HOME", "/tmp/hf")


def run(cmd: str) -> None:
    print(f"\n$ {cmd}", flush=True)
    subprocess.run(cmd, shell=True, check=True)


FILES = {
    'src/museumbot/common/prompts.py': '',
    'src/museumbot/generation/vllm_gen.py': '',
    'src/museumbot/generation/vllm_mix.py': '',
    'src/museumbot/generation/vllm_wiki.py': '',
    'data/wiki/full_pages.jsonl': '',
}

run("pip uninstall -y -q torchaudio; pip install -q vllm==0.31.0 python-dotenv")
run(f"git clone -q -b restructure-src https://github.com/massidale/museumbot {REPO}")
run(f"git -C {REPO} checkout -q 65c8c7e && git -C {REPO} log --oneline -1")
run(f"{sys.executable} {REPO}/kaggle/patch_vllm_turing.py")
for path, data in FILES.items():
    p = Path(REPO) / path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(zlib.decompress(base64.b64decode(data)))
run(f"PYTHONPATH={REPO}/src {sys.executable} -m museumbot.generation.vllm_wiki "
    f"--pages {REPO}/data/wiki/full_pages.jsonl --out {OUT}")
